INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (51, 17, 'run batch-8', 'work', 'done', NULL, '2026-10-15, authoring/data (batch-8 up to media, stash 6d1be84, qgen validate OK), authoring/RUNBOOK.md, plan 17; stopped at media; fix: task 1128, resume: task 1129', 'Batch-8 stopped at media in run 1068 (decision 205: batch-8 fails at media: how to go on?). This run doesn''t run the batch: it does decision 205''s six steps, in order, instead of the RUNBOOK.

