INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (52, 17, 'needs_work of batch-7/8 per decision 3', 'work', 'dropped', NULL, 'folded into task 53: QC batch-8 (phase 4): one plain qgen rework after batch-8''s QC covers batch-7''s backlog and batch-8''s, per decision 3; at -100 with a lower id, task 52 would have run before that QC and reworked batch-8 twice', 'Resolve the `needs_work` questions (33 at plan time, batch-7''s and older; batch-8''s too if it is merged) the way pm decision 3 says. Waits on decision 3.

