INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (97, 21, 'LUI-1: before/after comparison and close-out', 'work', 'done', NULL, '2026-10-12, plans/15a-ui-translation.md, plans/project.md; throw-away Playwright before (e1218f2) vs after: 43 screens pixel-identical (picker <1 px blur noise), texts and aria/title identical; worktree and temp files removed', 'Show that plan 21 changed nothing visible in Spanish, then close LUI-1.

