INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (108, 4, 'write plan: Audit report media.py licenses (PUB-1)', 'plan', 'done', 1000, '2026-10-11, pm plan 52, plans/17-publishing.md', 'Write the plan for part 2 of the masterplan (plan 4): `pm plan add 4 "Audit report media.py licenses" --priority 700`.

