INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (191, 38, 'Content target: estimate games per player, write the decision (OQ-32)', 'work', 'done', NULL, '2026-10-11, pm decision 21 (estimate in body); no files', 'Part 1 of plan 38. Prepare the OQ-32 decision; estimate only, no simulation (CT-2, `qgen report --simulate`, is S4). Can start now: use drafts where answers are missing and say so in the body.

