INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (201, 41, 'Multiplayer: facts, options, write the decision(s) (OQ-37)', 'work', 'done', NULL, '2026-10-11, pm decisions 23 (competitive format) and 24 (input and couch co-op), task 202 pending on both; burn numbers from a throw-away sim (deleted); external facts from memory (no web access), re-check in 202', 'Part 1 of plan 41. Prepare the OQ-37 decision(s); no code.

