INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (204, 42, 'Freesound: facts, options, write the decision', 'work', 'done', NULL, '2026-10-13, decision 82 (no files)', 'Part 2 of plan 42. Prepare the Freesound decision; no code, no picks, never contact Freesound/UPF.

