INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (308, 52, 'PUB-1 close-out: tally in plans/17-publishing.md', 'work', 'done', NULL, '2026-10-11, plans/17-publishing.md', 'Run `trivia-media licenses` (built by the previous task of this plan) and update `plans/17-publishing.md`:

