INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (670, 88, 'Scripted store screenshots at 1920×1080', 'work', 'done', NULL, '2026-10-13, authoring/store/screenshots.mjs, plans/17a-store-page.md (new: Screenshots), plans/README.md, directory.md, .gitignore (authoring/store/out/), flake.nix (xvfb in the dev shell); 30 PNGs rendered offline from the dev shell (es, es-ES 10 each; en, de 5: no pools); decision 79 → gamemaster; follow-up task 673 (en/de re-run); check, test, build, qgen validate pass', 'Plan 88 task 5.

