INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (684, 90, 'create tasks for plan 90', 'split', 'done', 1000, '2026-10-13, tasks 685, 686, 687 (tasks.sql only)', 'Split plan 90 into tasks and identify all decisions that need to be made. If the plan already has tasks,
