INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (701, 93, 'Plan 93 close-out: docs, how-tos, decision 93 consequences', 'work', 'done', 540, '2026-10-13, plans/11-steam.md (ST-5 reports half [x]; launch section left to task 862), plans/13-game-modes.md MD-6, plans/04-ui-tv-display.md flag list, plans/project.md, README.md how-tos (pull player reports, a player pasted a report), authoring/QC.md --pull bullet, AGENTS.md qgen line, directory.md state/reports-pulled.json + state/report-token; decision 93 consequences. plans/18 already covered by task 699.', 'Plan 93 task 6 (read the plan body). After the other plan 93 tasks (tasks 699, 859, 700, 860). The earlier Steam-thread/email text is dropped.

