INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (724, 76, 'Browser game: back up a corrupt or newer save (per decision 98)', 'work', 'done', NULL, '2026-10-13, app/server/main.py, app/server/save.py, app/client/src/lib/store.ts, app/client/src/lib/engine.ts, locales es/en/de, plans/decisions.md, README.md, directory.md, code-review.md', 'Follow-up of `task 540: Review engine bridge, stores and boot`. Do what `decision 98: Browser game: corrupt or newer state/game.json` answered.

