INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (725, 76, 'Catalog text for the bad_save error', 'work', 'done', NULL, '2026-10-13, app/client/src/locales/es.ts, en.ts, de.ts, code-review.md', 'Follow-up of `task 541: Review API client, types and errors` (`code-review.md` `## Part 4`).

