INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (751, 98, 'Packs as optional installs (decision 66, game side)', 'work', 'done', NULL, '2026-10-13, app/data/bundles/colombia/pool.json, app/data/pool.json, app/client/src/{engine/pool.ts,lib/data.ts,engine/test/fixtures.ts,engine/*.test.ts}, app/client/credits.ts, app/desktop/{resolve,stage-media}.mjs, app/server/{paths,media_cache,http_base}.py, authoring/tools/{pool_export,translations,layout,qgen,patch_notes}.py, authoring/tools/sim/load.ts, authoring/server/main.py, authoring/steam/release_check.py, authoring/store/screenshots.mjs, plans/decisions.md (D-94), plans/22-bundles.md, directory.md, README.md', 'Plan 98 part 3. decision 66: Price model (OQ-33): non-base bundles ship as free DLC with optional install. Independent of RG-5''s answer. Plan 89''s task 748 (DLC depots) waits on this.

