INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (1038, 129, 'PUB-7 name and trademark check: findings and decision', 'work', 'done', NULL, '2026-10-14, plans/17-publishing.md (Name check (PUB-7)); decision 176 pending, task 1039 waits on it', 'Part 2 of `plan 129: Partner account, name check and AI terms (PUB-6, PUB-7, PUB-10)`. Research only; never file anything, buy a domain or contact anyone.

