INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (1127, 137, 'Rename the gamemaster menu''s «Dificultad y paquetes de preguntas» row and dialog title now that it holds the answers switch', 'work', 'done', NULL, '2026-10-15, overlay.settings → «Ajustes de la partida» / «Game settings» / «Spieleinstellungen» (es-ES inherits es): locales/{es,en,de}.ts, style/{es,en,de}.md glossary, Overlay.svelte, GameSettings.svelte comments, directory.md, plans/04-ui-tv-display.md; check, test, build, qgen validate, gallery game-settings + menu-gamemaster in es, es-ES, en, de', 'Follow-up of `task 1124: UI: answers switch on the configure screen and in the game settings dialog`.

