INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (1181, 89, 'Media fetch: flag undecodable or truncated source images', 'work', 'done', NULL, '2026-10-15, authoring/tools/download.py (file_problem: magick decode, truncated/undecodable), media.py (checked, apply_pick, mark_broken; trivia-media sync checks), qgen.py (record downloads+checks picks → needs_work; batch sync marks broken), providers licence_verdict broken-file reason, server pick, MediaPanel label; q-0641 media file_problem + needs_work (export); docs plans/06, 08, decisions.md, AGENTS.md. Cache scan: only e2f8b6ba83a2ab2d.jpg truncated; 4 benign libpng/libtiff/libjpeg warnings pass', 'Found by `task 1180: stage-media: CMYK and truncated JPEGs break trivia-desktop-build` on 2026-10-15.
