INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web, model, worktree) VALUES (1463, 165, 'Mode and age screens: build, gallery review loop until approved', 'work', 'done', NULL, '2026-10-17, plans/13-game-modes.md, plans/15a-ui-translation.md', 'Part 6 of `plan 165: Multiplayer UI strings and gallery`. Design: `decision 314: Multiplayer screens reviewed in /gallery?` and the review decisions that follow it in this task.

