INSERT INTO decision (id, subject, status, options, body, intro, answer, reason, created_at, closed_at, created_by_task, signoff, kind, decided_by_task, consequences) VALUES (164, 'Screen gallery reviewed? (de)', 'answered', '["reviewed, flags in /gallery", "reviewed, nothing to fix"]', 'Review the screen gallery in `de` (`plan 100: UI wording: style guides, TV-check fixes, screen gallery`). Gallery rendered 2026-10-14 by `task 804: Screen gallery review decisions per UI language`: 44 shots, every visible text keyed.

