INSERT INTO decision (id, subject, status, options, body, intro, answer, reason, created_at, closed_at, created_by_task, signoff, kind, decided_by_task, consequences) VALUES (173, 'DLC store texts approved? (colombia)', 'pending', '["Approved as drafted", "Approved with fixes (list them)"]', 'Read plans/17a-store-page.md, section ''Free DLC'', block `colombia` (`task 783: Free DLC store texts in 17a`): name, short description (≤ 300), About This Content, for es (also es-ES) and en.
