INSERT INTO decision (id, subject, status, options, body, intro, answer, reason, created_at, closed_at, created_by_task, signoff, kind, decided_by_task, consequences) VALUES (454, 'QC batch-24: which changes?', 'pending', '["recommended set: review.md media-giveaway check", "all", "none"]', 'Audit (authoring/reports/batch-24.md): 3 major findings on approved questions, all media (q-8280 file title names Bogotá, q-8293 title names Barranquilla, q-8300 essential photo of Maluma shows the answer), 2 of them also giveaway. Audit agreement 54/60 (90 %). No spot check recorded yet. Proposal: review.md, add a check that the media file title/caption and the image subject never name or show the answer (essential media of a person in who-is questions, illustrative media titles naming the place).', 'The AI audit of the latest Colombian trivia batch found several approved questions whose pictures name or show the answer. The choice is whether to change the instructions the AI follows so that fewer such pictures get through. Nothing waits for the answer; it is acted on afterwards.', NULL, NULL, '2026-10-24T07:54:27Z', NULL, 1751, NULL, 'rule', NULL, '');
INSERT INTO decision (id, subject, status, options, body, intro, answer, reason, created_at, closed_at, created_by_task, signoff, kind, decided_by_task, consequences) VALUES (455, 'batch-25: health ✗, look at it?', 'pending', '["Looked at it"]', 'batch-25 health ✗ (authoring/reports/batch-25.md, batch-25 column): drop rate 40.8 % (≤20), needs_work overlap 2.5 % (≤1), overlap rate 35.4 % (≤20), merged/slots 11–15 21.6 % (≥55), max final−target gap 11–15 1.78 (≤1.50), top lens 27.0 % (≤25), mean fun 3.32 (≥3.40), $ per approved $0.38 (≤0.35). The pool is filling up, so overlap rises.', 'A batch of Colombian-Spanish trivia questions was just written, and several quality measures fell outside the limits we set, such as too many drafts dropped for overlap with existing questions. The batch was kept and generation continues; the question is whether the developer wants to look at the numbers and act on them.', NULL, NULL, '2026-10-24T09:19:26Z', NULL, 1752, NULL, 'rule', NULL, '');
